import os
import tempfile
from dataclasses import dataclass, field

import git


HOOKS_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "hooks")


@dataclass
class GitConfig:
    branch: str = "main"
    depth: int = 1
    hooks_path: str = HOOKS_DIR
    extra_options: list = field(default_factory=list)


def _build_clone_options(config):
    opts = []
    base = f"--branch {config.branch} --depth {config.depth}"
    if config.hooks_path:
        base += f" --config core.hooksPath={config.hooks_path}"
    opts.append(base)
    opts.extend(config.extra_options)
    return opts


def get_git(url, dest=None, config=None):
    if config is None:
        config = GitConfig()
    if dest is None:
        dest = tempfile.mkdtemp(prefix="dynamic-git-")

    multi_options = _build_clone_options(config)
    repo = git.Repo.clone_from(url, dest, multi_options=multi_options)
    return repo
